    z_t976_destroy(p->pendingTyperef);
    z_t976_destroy(p->pendingTyperefUnit);
    z_t889_destroy(p->unitTypesById);
    z_t1349_destroy(&p->decls);
    z_t1325_destroy(p->declByTypeId);
    z_t1325_destroy(p->unitRootByName);
    z_t1325_destroy(p->refDecl);
    z_t1369_destroy(&p->pendingDefs);
    z_t1275_destroy(p->enteredUnits);
    z_t683_destroy(&p->declProxyTids);
    z_t205_destroy(&p->declProxyUnits);
